sys_script_include.script:
var EventUtilsClient = Class.create();
EventUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEventDetails: function() {
        var eventId = this.getParameter('sysparm_eventId');

        var eventGR = new GlideRecord('x_1790227_event_ma_event');
        if (eventGR.get(eventId)) {
            var eventDetails = {

                name: gr.getValue('u_event_name'),
                date: gr.getDisplayValue('u_event_date'),
                location: gr.getValue('u_location'),
                status: gr.getValue('u_status'),
                contact: gr.getValue('u_contact_person'),
                email: gr.getValue('u_email')

            };
            return JSON.stringify(eventDetails);
        } else {
            return JSON.stringify({
                error: 'Event not found'
            });
        }
    },
    isVIPEvent: function() {
        var eventId = this.getParameter('sysparm_eventId');

        var eventGR = new GlideRecord('x_1790227_event_ma_event');
        if (eventGR.get(eventId)) {
            return eventGR.getValue('u_vip') == true;
        }
        return false;
    },

    rescheduleEvent: function() {
        var eventId = this.getParameter('sysparm_eventId');
        var newDateInput = this.getParameter('sysparm_newDate');

        if (newDateInput.length == 10) { 
            newDateInput += " 09:00:00"; 
        }

        var gr = new GlideRecord('x_1790227_event_ma_event');
        if (gr.get(eventId)) {
            gr.u_event_date = newDateInput;
            gr.update();

            // Notify Planner
            gs.eventQueue('x_1790227_event_ma.event.reschedule.notify', gr, gr.assigned_to, gr.sys_id);

            return 'success';
        }
        return 'failure';
    },



    fetchEventTasks: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_event_task');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.getValue('number') + ' | ' + gr.getValue('u_task_name'));
        }
        return result.length ? result.join('\n') : 'No tasks found';
    },

    fetchEventAttendees: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_attendee');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.getValue('u_attendee_name') + ' | ' + gr.getValue('u_email'));
        }
        return result.length ? result.join('\n') : 'No attendees found';
    },

    fetchEventVendors: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_vendor');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.getValue('u_vendor_name') + ' | ' + gr.getValue('u_email'));
        }
        return result.length ? result.join('\n') : 'No vendors found';
    },

    fetchEventBudgetDetails: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(
                'Total: ' + gr.getValue('u_total_budget') +
                ', Spent: ' + gr.getValue('u_amount_spent') +
                ', Remaining: ' + gr.getValue('u_amount_remaining')
            );
        }
        return result.length ? result.join('\n') : 'No budget entries found';
    },

    fetchEventFeedback: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(
                'Attendee: ' + gr.getDisplayValue('u_attendee_id') +
                ', Rating: ' + gr.getValue('u_rating') +
                ', Comments: ' + gr.getValue('u_comments')
            );
        }
        return result.length ? result.join('\n') : 'No feedback found';
    },

    calculateRemainingBudget: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_budget');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push('Remaining Budget: ' + gr.getValue('u_amount_remaining'));
        }
        return result.length ? result.join('\n') : 'Budget entry not found';
    },

    type: 'EventUtilsClient'
});
